mapper.select:
select id, strategy, id_count, last_id, elapsed_millis, create_time
from classic_id_generated
where strategy = #{strategy}
order by id desc
limit #{limit}

select id, mode, expected_count, actual_count, lock_acquired, lock_timed_out,
       lost_updates, elapsed_millis, create_time
from classic_lock_lab_result
where mode = #{mode}
order by id desc
limit #{limit}

select id, biz_key, algorithm, limit_count, window_seconds, attempts,
       first_burst_allowed, second_burst_allowed, distributed, create_time
from classic_rate_limit_lab_result
where biz_key = #{bizKey}
order by id desc
limit #{limit}
